from collections import Counter

def transform(grid):
    # Each 3x3 tile encodes one output cell. Colors 0 and 5 are background.
    out = []
    for r in range(0, len(grid), 3):
        row = []
        for c in range(0, len(grid[0]), 3):
            counts = Counter(
                grid[i][j]
                for i in range(r, min(r + 3, len(grid)))
                for j in range(c, min(c + 3, len(grid[0])))
                if grid[i][j] not in (0, 5)
            )
            row.append(counts.most_common(1)[0][0] if counts else 0)
        out.append(row)
    return out
